.cbf-summary__head {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--spacing-300);
}
.cbf-summary__title {
  margin: 0;
  font-size: var(--font-size-400, 1.125rem);
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
}
.cbf-summary__actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--spacing-200);
}
.cbf-summary__modified {
  margin: 0 0 var(--spacing-300);
  color: var(--color-content-default-tertiary);
}
.cbf-summary__basics {
  display: flex;
  flex-wrap: wrap;
  gap: var(--spacing-500);
  align-items: flex-start;
}
.cbf-summary__basics-main {
  flex: 1;
  min-width: min(100%, 420px);
}
.cbf-summary__dl {
  display: grid;
  grid-template-columns: 210px 1fr;
  margin: 0;
}
.cbf-summary__dl > dt {
  grid-column: 1;
  text-align: right;
  padding: var(--spacing-300) var(--spacing-400);
  border-top: 1px solid var(--color-border-default-subtle, var(--color-border-default));
  color: var(--color-content-default-secondary);
  font-weight: var(--typography-font-weight-medium);
}
.cbf-summary__dl > dd {
  grid-column: 2;
  margin: 0;
  padding: var(--spacing-300) var(--spacing-400);
  border-top: 1px solid var(--color-border-default-subtle, var(--color-border-default));
  min-width: 0;
}
.cbf-summary__dl > dt:first-of-type,
.cbf-summary__dl > dt:first-of-type + dd {
  border-top: 0;
}
.cbf-summary__desc-lede {
  margin: 0 0 var(--spacing-200);
}
.cbf-summary__desc {
  margin: 0;
  color: var(--color-content-default-secondary);
  max-width: 80ch;
}
.cbf-summary__note {
  display: block;
  margin-top: 2px;
  color: var(--color-content-default-tertiary);
}
.cbf-summary__subtable {
  width: 100%;
  border-collapse: collapse;
}
.cbf-summary__subtable th,
.cbf-summary__subtable td {
  text-align: left;
  padding: var(--spacing-200) var(--spacing-300);
  border: 1px solid var(--color-border-default);
  font-size: var(--font-size-150, 0.875rem);
  vertical-align: top;
}
.cbf-summary__subtable th {
  background: var(--color-background-elevation-sunken, #f4f4f4);
  font-weight: var(--typography-font-weight-semibold);
  white-space: nowrap;
}
.cbf-summary__map {
  width: 320px;
  flex: none;
}
.cbf-summary__map-canvas {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 220px;
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-200);
  background:
    repeating-linear-gradient(
      0deg,
      transparent 0 23px,
      color-mix(in srgb, var(--color-background-brand) 6%, transparent) 23px 24px
    ),
    repeating-linear-gradient(
      90deg,
      transparent 0 23px,
      color-mix(in srgb, var(--color-background-brand) 6%, transparent) 23px 24px
    ),
    color-mix(
      in srgb,
      var(--color-content-utility-success, #15803d) 8%,
      var(--color-background-elevation-raised)
    );
}
.cbf-summary__map-cap {
  margin: var(--spacing-200) 0 0;
  font-style: italic;
  color: var(--color-content-default-tertiary);
}
.cbf-summary__contacts,
.cbf-summary__section-note {
  margin: 0;
}
.cbf-summary__contacts {
  width: 100%;
  border-collapse: collapse;
}
.cbf-summary__contacts th,
.cbf-summary__contacts td {
  text-align: left;
  padding: var(--spacing-200) var(--spacing-400);
  border-bottom: 1px solid var(--color-border-default-subtle, var(--color-border-default));
}
.cbf-summary__contacts th {
  background: var(--color-background-elevation-sunken, #f4f4f4);
  font-weight: var(--typography-font-weight-semibold);
}
.cbf-summary__section-note {
  color: var(--color-content-default-secondary);
}
.cbf-summary .cbf-doc-link {
  color: var(--color-background-brand);
  text-decoration: underline;
}
.cbf-summary .esa-collapsible + .esa-collapsible {
  margin-top: var(--spacing-300);
}
.cbf-lipd__panel {
  padding-block-start: var(--spacing-400);
}
.cbf-lipd__intro {
  margin: 0;
  color: var(--color-content-default-secondary);
  max-width: 90ch;
}
.cbf-lipd__toolbar {
  align-items: center;
}
.cbf-lipd__scroll {
  overflow-x: auto;
}
.cbf-lipd__doctable {
  overflow: visible;
}
@media (max-width: 1024px) {
  .cbf-lipd__doctable {
