  align-items: center;
  gap: var(--spacing-100);
  color: var(--color-content-utility-success, #15803d);
  font-weight: var(--typography-font-weight-semibold);
  white-space: nowrap;
}
.cbf-lipd .cbf-none {
  color: var(--color-content-default-secondary);
}
.cbf-lipd .cbf-na {
  color: var(--color-content-default-tertiary);
  font-style: italic;
}
.cbf-lipd .cbf-check--locked {
  color: var(--color-content-default-tertiary);
  font-weight: var(--typography-font-weight-medium);
}
.cbf-lipd .cbf-reappr {
  display: inline-block;
  margin-inline-start: var(--spacing-200);
  padding: 2px var(--spacing-200);
  border-radius: var(--radius-full, 9999px);
  background: var(--color-content-utility-warning, #b45309);
  color: var(--color-content-default-knockout, #fff);
  font-size: var(--font-size-100, 0.8125rem);
  font-weight: var(--typography-font-weight-semibold);
  white-space: nowrap;
}
